// ── helpers ──────────────────────────────────────────────────────────

// buildPageData populates DVEPageData from the URI registry entry and optional query string.
// If dveManager and validationCore are available, it fetches real metrics and records.
func (h *DVEProxyHandler) buildPageData(dve *services.DVEURI, query string) *DVEPageData {
	data := &DVEPageData{
		DVEID:     dve.DVEID,
		FullURI:   dve.FullURI,
		Status:    dve.Status,
		WalletAddr: dve.WalletAddr,
		CreatedAt: dve.CreatedAt,
		Query:     query,
		Metrics: DVEPageMetrics{
			TotalValidations: 0,
			SuccessRate:      100.0,
			AverageScore:     0.0,
		},
		Records: []DVEPageRecord{},
		Total:   0,
	}

	// Phase 5: Wire real data from DVEManager and ValidationCore
	if h.dveManager != nil {
		node, err := h.dveManager.GetNode(dve.DVEID)
		if err == nil && node != nil {
			data.NodeIP = node.IPAddress
			data.TEEType = node.TEEType
			data.ReputationScore = node.ReputationScore
			data.LastHeartbeat = node.LastHeartbeat
			data.UptimeSeconds = node.UptimeSeconds
			if data.Status == "" {
				data.Status = node.Status
			}
		}

		metrics, err := h.dveManager.GetNodeMetrics(dve.DVEID)
		if err == nil && metrics != nil {
			data.Metrics.SuccessRate = metrics.SuccessRate
			data.Metrics.AverageScore = metrics.AverageScore
		}
	}

	if h.validationCore != nil {
		tasks, err := h.validationCore.GetValidationTasks(&validation.TaskFilter{})
		if err == nil {
			// Filter tasks by assigned node ID
			var filtered []*objects.ValidationTask
			for _, t := range tasks {
				if t.AssignedNodeID == dve.DVEID {
					filtered = append(filtered, t)
				}
			}
			data.Records = buildPageRecords(filtered)
			data.Total = len(filtered)
			data.Metrics.TotalValidations = len(filtered)
		}
	}

	data.RewardPoolAddress = h.rewardPoolAddr
	return data
}

// buildPageRecords converts ValidationTask slice to DVEPageRecord slice for templates.
func buildPageRecords(tasks []*objects.ValidationTask) []DVEPageRecord {
	if len(tasks) == 0 {
		return []DVEPageRecord{}
	}
	records := make([]DVEPageRecord, 0, len(tasks))
	for _, t := range tasks {
